switch (res.stop_reason) {
  case "refusal":
    log.warn("refusal", { requestId: res._request_id });
    return { ok: false, message: "We can't help with that request." };
  case "max_tokens":
    throw new TruncatedError(); // never run tools from this turn
  case "tool_use":
    return runToolsWithApproval(res.content); // HITL gate in code
  case "end_turn":
    return { ok: true, text: textOf(res.content) };
}

