def create_pull_request(repo: str, title: str, body: str, *, user_id: str):
    token = vault.get_token(user_id, provider="github")
    r = requests.post(
        f"https://api.github.com/repos/{repo}/pulls",
        headers={"Authorization": f"Bearer {token}"},
        json={"title": title, "body": body, "head": "agent-branch", "base": "main"},
        timeout=30,
    )
    return {"content": f"PR #{r.json()['number']} created"}

